function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
function notice(message,type=''){const el=$('#source-notice');el.innerHTML=message;el.className='source-notice '+type;}
function options(selector,values,allLabel){const el=$(selector),prior=el.value;el.innerHTML=`<option value="all">${allLabel}</option>`+values.map(v=>`<option value="${e(v)}">${e(v)}</option>`).join('');el.value=values.includes(prior)?prior:'all';}
function activeReportId(){return REPORTS[state.view]?state.view:state.reportView;}
function activeModel(){return buildReport(data?.records||[],state,profiles,data?.meta||{},activeReportId());}
function fillFilters(){
  const records=data?.records||[];const unique=(field,rows=records)=>[...new Set(rows.map(r=>r[field]).filter(Boolean))].sort();
  options('#region-filter',unique('region'),'All regions');$('#region-filter').value=state.region;
  const districtRows=state.region==='all'?records:records.filter(r=>r.region===state.region);
  options('#district-filter',unique('district',districtRows),'All districts');if(!unique('district',districtRows).includes(state.district))state.district='all';$('#district-filter').value=state.district;
  for(const [id,key,label]of [['#vendor-filter','vendor','All vendors'],['#severity-filter','severity','All severities'],['#label-filter','site_label','All priorities'],['#cause-filter','root_cause','All causes']]){options(id,unique(key),label);$(id).value=state[key];}
  $('#period-filter').value=state.period;$('#impact-filter').value=state.service_impact;$('#scope-filter').value=state.scope;
  if(data){$('#period-filter').min=data.meta.min_date.slice(0,7);$('#period-filter').max=data.meta.max_date.slice(0,7);}
  const definition=REPORTS[activeReportId()],weekly=definition?.mode.includes('week');
  $('#period-field').hidden=weekly;$('#week-field').hidden=!weekly;$('#year-field').hidden=!weekly;
  $('#period-label').textContent=definition?.mode==='year'?'Review through':'Review month';
  $('#impact-filter').value=definition?.impact==='NSA'?'NSA':'Outage';$('#impact-filter').disabled=true;
  $('#scope-filter').options[0].textContent='Power BI page criteria';
  if(data){const first=Number(data.meta.min_date.slice(0,4)),last=Number(data.meta.max_date.slice(0,4));$('#year-filter').innerHTML=Array.from({length:last-first+1},(_,i)=>`<option value="${first+i}">${first+i}</option>`).join('');$('#year-filter').value=String(state.year);}
  $('#week-filter').innerHTML=Array.from({length:weeksInYear(state.year||2026)},(_,i)=>{const r=weekRange(state.year||2026,i+1);return `<option value="${i+1}">W${String(i+1).padStart(2,'0')} · ${r.start.slice(5)} – ${r.end.slice(5)}</option>`;}).join('');$('#week-filter').value=String(state.week);
}
function setData(dataset,origin){
  if(!dataset?.records?.length||!dataset.meta?.min_date||!dataset.meta?.max_date)throw new Error('The dataset has no valid dated records.');
  const wasLatest=state.followLatest;
  data=dataset;source=origin;profile=dataset.meta.profile||profile;
  if(wasLatest||!state.year){state.period=dataset.meta.max_date.slice(0,7);state.year=Number(dataset.meta.max_date.slice(0,4));state.week=weekNumber(dataset.meta.max_date);}recordsById=new Map(data.records.map(r=>[r.id,r]));
  if(!coverageFor(data.meta,state.period))state.period=data.meta.max_date.slice(0,7);
  state.page=0;fillFilters();$('#nav-count').textContent=number(data.records.length);
  $('#sidebar-source').textContent=origin==='database'?'Live PostgreSQL · 30s refresh':origin==='preview'?'Local import preview':data.meta.source_drive_id?'Cumulative data snapshot':'Power BI model snapshot';$('#sidebar-dot').classList.toggle('live',origin==='database');
  $('#footer-source').textContent=`Source records: ${dateName(data.meta.min_date)} – ${dateName(data.meta.max_date)}`;
  if(origin==='database')notice(`${icon('database')}<span>PostgreSQL data · <b>${number(data.records.length)}</b> records · source through <b>${dateName(data.meta.max_date)}</b></span><span class="notice-end">Auto refresh · 30s</span><button class="text-button" id="refresh-now">Refresh now</button>`,'success');
  else notice(`${icon('info')}<span>${origin==='preview'?'Local import preview':data.meta.source_drive_id?'Cumulative data snapshot':'Power BI model snapshot'} · <b>${number(data.records.length)}</b> records through <b>${dateName(data.meta.max_date)}</b>. ${origin==='preview'?'These records have not been saved to PostgreSQL.':'Database synchronization is not active.'}</span><button class="text-button notice-end" data-go="settings">Connect database ${icon('arrow')}</button>`,'warn');
  if(config.privateSnapshot&&origin==='snapshot')$('#source-notice').innerHTML+=`<a href="${e(config.privateSnapshot)}" download="stc-COW-performance-data.json.gz" class="text-button notice-end">Download dashboard data ${icon('download')}</a>`;
  $('#export-csv').disabled=false;$('#print-review').disabled=false;render();if(origin==='database')startAutoRefresh();
}
function baseRecords(){return data?reportScope(data.records,state,profiles,activeReportId()):[];}
function periodRecords(period=state.period){return !data?[]:period===state.period?activeModel().now.rows:baseRecords().filter(r=>r.created_date?.slice(0,7)===period);}
function current(){return summarize(periodRecords());}
function compare(){return data?activeModel().prev.summary:null;}
function delta(a,b,higherBetter=false,pp=false){
  const d=pp?(num(a)&&num(b)?a-b:null):percentageChange(a,b);if(d===null)return '<span class="delta">No comparison</span>';
  const good=d===0?'':(higherBetter?d>0:d<0)?'good':'bad';return `<span class="delta ${good}">${d===0?'':icon(d>0?'up':'down')}${number(Math.abs(d),1)}${pp?' pp':'%'}</span>`;
}
function kpi(label,value,unit,graphic,a,b,note,sub,higher=false,pp=false,featured=false){return `<article class="kpi ${featured?'featured':''}"><div class="kpi-top"><span class="kpi-label">${label}</span><span class="kpi-icon">${icon(graphic)}</span></div><div class="kpi-value">${value}${unit?`<small>${unit}</small>`:''}</div><div class="kpi-footer">${delta(a,b,higher,pp)}<span>vs previous month</span></div><div class="kpi-note">${note}</div>${sub||''}</article>`;}
function kpis(s,p){return `<div class="kpis">${kpi('Total tickets',number(s.tickets),'','ticket',s.tickets,p?.tickets,`${e(state.service_impact==='all'?'All impacts':state.service_impact)} · Power BI COUNTROWS`,'',false,false,true)}${kpi('Recorded restoration',hours(s.durationMinutes),'hrs','clock',s.durationMinutes,p?.durationMinutes,`${number(s.durationCount)} recorded durations · ${number(s.missingDuration)} missing`)}${kpi('Mean restoration',hours(s.mttr),'hrs','activity',s.mttr,p?.mttr,'Mean of valid recorded durations')}${kpi('SLA compliance',number(s.slaCompliance,1),'%','check',s.slaCompliance,p?.slaCompliance,`${number(s.breached)} breached / ${number(s.slaEligible)} eligible · ${number(s.slaExcluded)} excluded`,'',true,true)}</div>`;}
function metricStrip(s){return `<div class="mini-metrics"><div><b>${number(s.sites)}</b><span>Sites with tickets</span></div><div><b>${number(s.repeatSites)}</b><span>Sites with 2+ tickets</span></div><div><b>${number(s.uncleared)}</b><span>Uncleared in source</span></div><div><b>${hours(s.impactMinutes)} <small>hrs</small></b><span>Service interruption · ${number(s.impactCount)} intervals</span></div></div>`;}
function trendPanel(){
  const trend=monthlyTrend(baseRecords(),state.period,data.meta),w=760,h=230,left=40,right=55,top=18,bottom=37,plotH=h-top-bottom,plotW=w-left-right;
  const maxTickets=Math.max(1,...trend.map(t=>t.tickets||0)),maxHours=Math.max(1,...trend.map(t=>(t.durationMinutes||0)/60));
  const nice=(n)=>{const p=10**Math.floor(Math.log10(n));return Math.ceil(n/p/2)*p*2;};
  const yMax=nice(maxTickets),hMax=nice(maxHours),gap=plotW/12,bw=gap*.42;
  let svg=`<svg class="trend-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Monthly tickets as purple columns and recorded restoration hours as a pink line. Left axis: tickets. Right axis: hours."><text x="${left}" y="8">Tickets</text><text x="${w-right+8}" y="8">Hours</text>`;
  for(let i=0;i<5;i++){const y=top+plotH-i*plotH/4;svg+=`<line x1="${left}" y1="${y}" x2="${w-right}" y2="${y}" stroke="#f0ecf5" ${i?'stroke-dasharray="3 4"':''}/><text x="${left-9}" y="${y+3}" text-anchor="end">${number(yMax*i/4)}</text><text x="${w-right+12}" y="${y+3}">${number(hMax*i/4)}</text>`;}
  let segment=[];const segments=[];
  trend.forEach((t,i)=>{const x=left+gap*i+gap/2,active=t.month===state.period,bh=(t.tickets||0)/yMax*plotH;
    svg+=`<rect x="${x-bw/2}" y="${top+plotH-bh}" width="${bw}" height="${bh}" rx="3" fill="${active?'#4f008c':'#dfcdeb'}" tabindex="0" role="button" data-month="${t.month}" aria-label="${monthName(t.month)}: ${t.covered?number(t.tickets)+' tickets':'outside source coverage'}"><title>${monthName(t.month)}: ${t.covered?number(t.tickets)+' tickets · '+hours(t.durationMinutes)+' restoration hours':'outside source coverage'}</title></rect>`;
    svg+=`<text x="${x}" y="${h-17}" text-anchor="middle" class="${active?'active-label':''}">${new Date(t.month+'-15').toLocaleDateString('en-GB',{month:'short',timeZone:'UTC'})}</text><text x="${x}" y="${h-3}" text-anchor="middle" style="font-size:7px">${t.month.slice(0,4)}</text>`;
    if(num(t.durationMinutes)){segment.push({x,y:top+plotH-t.durationMinutes/60/hMax*plotH,value:t.durationMinutes,month:t.month});}else if(segment.length){segments.push(segment);segment=[];}
  });if(segment.length)segments.push(segment);
  for(const points of segments){svg+=`<polyline points="${points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="#ff375e" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>`;for(const p of points)svg+=`<circle cx="${p.x}" cy="${p.y}" r="3" fill="white" stroke="#ff375e" stroke-width="1.8"><title>${monthName(p.month)}: ${hours(p.value)} recorded hours</title></circle>`;}
  svg+='</svg>';
  const priorYear=previousMonth(state.period,-12),s=current(),yoy=coverageFor(data.meta,priorYear)?summarize(periodRecords(priorYear)):null;
  return `<section class="panel"><div class="panel-title"><div><h2>Performance over time</h2><p>Monthly ticket volume and recorded restoration</p></div><div class="legend"><span><i></i>Tickets</span><span><i class="line"></i>Restoration hrs</span></div></div>${svg}<div class="chart-caption"><span>${monthName(previousMonth(state.period,-11),true)} – ${monthName(state.period,true)}</span><span>Tickets vs ${monthName(priorYear,true)} &nbsp;${delta(s.tickets,yoy?.tickets)}</span></div><details class="chart-data print-hide"><summary>View monthly values</summary><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Month</th><th>Tickets</th><th>Restoration hrs</th><th>Mean hrs</th></tr></thead><tbody>${trend.map(t=>`<tr><td>${monthName(t.month,true)}</td><td>${number(t.tickets)}</td><td>${hours(t.durationMinutes)}</td><td>${hours(t.mttr)}</td></tr>`).join('')}</tbody></table></div></details></section>`;
}
function focusPanel(records){
  const s=summarize(records),causes=groupBy(records,'root_cause'),regions=groupBy(records,'region'),sites=groupBy(records,'site_id').filter(g=>g.name!=='Unknown'&&g.tickets>=2),dominant=causes[0],region=regions[0],repeat=sites[0];
  const items=[
    {title:dominant?dominant.name:'No root cause data',body:dominant?`${number(dominant.tickets)} tickets, ${number(dominant.tickets/Math.max(s.tickets,1)*100,1)}% of this month’s volume. Recorded restoration: ${hours(dominant.durationMinutes)} hrs.`:'No tickets match the selected filters.'},
    {title:region?`${region.name} region`:'Regional view',body:region?`${number(region.tickets)} tickets and ${hours(region.durationMinutes)} restoration hrs. ${number(region.breached)} recorded SLA breaches.`:'Select another period or scope to review regional performance.'},
    {title:repeat?`${repeat.name} · recurring faults`:'Recurring faults',body:repeat?`${number(repeat.tickets)} tickets this month. ${number(s.repeatSites)} sites have two or more tickets under the selected filters.`:`${number(s.repeatSites)} sites have two or more tickets under the selected filters.`}
  ];return `<section class="panel focus-panel"><div class="panel-title"><div><h2>This month’s focus</h2><p>Priorities from the selected records</p></div><span class="focus-marker"></span></div><div class="focus-items">${items.map((v,i)=>`<div class="focus-item"><span class="focus-number">0${i+1}</span><div><h3>${e(v.title)}</h3><p>${e(v.body)}</p></div></div>`).join('')}</div></section>`;
}
function regionPanel(records){const groups=groupBy(records,'region'),prev=compare(),prevGroups=new Map(groupBy(periodRecords(previousMonth(state.period)),'region').map(g=>[g.name,g]));return `<section class="panel"><div class="panel-title"><div><h2>Regional performance</h2><p>Click a region to focus the monthly review</p></div><span class="section-count">${groups.length} regions</span></div><div class="data-table-wrap"><table class="region-table"><thead><tr><th>Region</th><th class="right">Tickets</th><th class="right">MoM</th><th class="right">Restore hrs</th><th class="right">SLA %</th></tr></thead><tbody>${groups.map(g=>`<tr><td><span class="region-name"><i class="region-dot"></i><button class="table-link" data-region="${e(g.name)}">${e(g.name)}</button></span></td><td class="right">${number(g.tickets)}</td><td class="right">${delta(g.tickets,prev?(prevGroups.get(g.name)?.tickets||0):null)}</td><td class="right">${hours(g.durationMinutes)}</td><td class="right"><span class="rate">${number(g.slaCompliance,1)}${num(g.slaCompliance)?'%':''}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No matching regional records.</td></tr>'}</tbody></table></div><p class="panel-foot">SLA is based on recorded outcomes after explicit exemptions.</p></section>`;}
function barsPanel(records,field,title,subtitle,limit=5){const groups=groupBy(records,field).slice(0,limit),total=summarize(records).tickets,max=Math.max(1,...groups.map(g=>g.tickets));return `<section class="panel"><div class="panel-title"><div><h2>${title}</h2><p>${subtitle}</p></div><span class="section-count">By tickets</span></div><div class="bars">${groups.map(g=>`<div><div class="bar-label"><button class="table-link" data-${field==='root_cause'?'cause':field==='district'?'district':'priority'}="${e(g.name)}">${e(g.name)}</button><span><b>${number(g.tickets)}</b> <span class="muted">${number(g.tickets/Math.max(total,1)*100,1)}%</span></span></div><div class="bar-track"><div class="bar-fill" style="width:${g.tickets/max*100}%"></div></div></div>`).join('')||'<div class="empty">No matching records.</div>'}</div><p class="panel-foot">${field==='root_cause'?'Select a cause to inspect its tickets. Source cause labels are preserved.':'Share of distinct tickets in the selected monthly scope.'}</p></section>`;}
function overview(){const rows=periodRecords(),s=summarize(rows),p=compare();return `<div class="section-heading"><div><h2>${e(monthName(state.period))} overview</h2><p>${e(state.region==='all'?'National network':state.region+' region')}${state.district!=='all'?' · '+e(state.district):''} · ${e(state.service_impact==='all'?'All service impacts':state.service_impact+' tickets')}</p></div><span class="period-badge">${icon('calendar')}<span>${e(monthName(state.period,true))}</span></span></div>${kpis(s,p)}<div class="dashboard-grid">${trendPanel()}${focusPanel(rows)}</div><div class="section-grid">${regionPanel(rows)}${barsPanel(rows,'root_cause','Top root causes','Highest ticket contribution in the selected month')}</div>${metricStrip(s)}${siteTable(rows,true)}${printNotes()}`;}
function causeView(){const rows=periodRecords(),groups=groupBy(rows,'root_cause'),s=summarize(rows);return `${kpis(s,compare())}<div class="section-grid">${barsPanel(rows,'root_cause','Root cause contribution','Top 8 causes by ticket volume',8)}${barsPanel(rows,'district','District contribution','Top 8 districts by ticket volume',8)}</div><section class="panel"><div class="panel-title"><div><h2>Root cause detail</h2><p>Ranked by recorded restoration hours</p></div><span class="section-count">${number(groups.length)} causes</span></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Root cause</th><th class="right">Tickets</th><th class="right">Share</th><th class="right">Restore hrs</th><th class="right">Mean hrs</th><th class="right">Breaches</th></tr></thead><tbody>${groups.sort((a,b)=>(b.durationMinutes||0)-(a.durationMinutes||0)).map(g=>`<tr><td><button class="table-link" data-cause="${e(g.name)}">${e(g.name)}</button></td><td class="right">${number(g.tickets)}</td><td class="right">${number(g.tickets/Math.max(s.tickets,1)*100,1)}%</td><td class="right">${hours(g.durationMinutes)}</td><td class="right">${hours(g.mttr)}</td><td class="right">${number(g.breached)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching causes.</td></tr>'}</tbody></table></div></section>`;}
function sortHeader(label,key){return `<button data-sort="${key}">${label}${icon(state.sort===key?(state.dir>0?'up':'down'):'sort')}</button>`;}
function sorted(rows){return [...rows].sort((a,b)=>{const x=a[state.sort],y=b[state.sort];if(x===null||x===undefined)return y===null||y===undefined?0:1;if(y===null||y===undefined)return -1;return (typeof x==='number'?x-y:String(x).localeCompare(String(y)))*state.dir;});}
function pager(total,size=25){const max=Math.max(1,Math.ceil(total/size));state.page=Math.min(state.page,max-1);return `<div class="pagination"><span>${total?number(state.page*size+1)+'–'+number(Math.min((state.page+1)*size,total)):'0'} of ${number(total)} ${state.view==='sites'?'sites':'records'}</span><div><button data-page="prev" ${!state.page?'disabled':''} aria-label="Previous page">Previous</button><span>Page ${state.page+1} / ${max}</span><button data-page="next" ${state.page>=max-1?'disabled':''} aria-label="Next page">Next</button></div></div>`;}
function siteTable(records,compact=false){let groups=groupBy(records,'site_id').filter(g=>g.name!=='Unknown').map(g=>({...g,site_id:g.name,region:[...new Set(g.rows.map(r=>r.region))].join(', '),district:[...new Set(g.rows.map(r=>r.district))].join(', ')}));
  if(compact)groups.sort((a,b)=>b.tickets-a.tickets||(b.durationMinutes||0)-(a.durationMinutes||0));else groups=sorted(groups);
  const total=groups.length;if(compact)groups=groups.slice(0,5);else{if(state.query)groups=groups.filter(g=>[g.name,g.region,g.district,...g.rows.map(r=>r.site_name)].some(v=>String(v||'').toLowerCase().includes(state.query.toLowerCase())));}
  const filteredTotal=groups.length;if(!compact){state.page=Math.min(state.page,Math.max(0,Math.ceil(filteredTotal/25)-1));groups=groups.slice(state.page*25,state.page*25+25);}
  return `<section class="panel"><div class="panel-title"><div><h2>${compact?'Sites to review':'Site performance detail'}</h2><p>${compact?'Highest ticket recurrence in the selected month':'Compare recurrence, restoration and SLA outcomes'}</p></div>${compact?'<button class="text-button" data-go="sites">View all sites '+icon('arrow')+'</button>':`<span class="section-count">${number(total)} sites</span>`}</div>${compact?'':`<div class="table-tools"><label class="search">${icon('search')}<input id="table-query" type="search" placeholder="Search COW, location or district" value="${e(state.query)}" aria-label="Search sites"></label><span class="muted section-count">Click a COW to inspect its tickets</span></div>`}<div class="data-table-wrap"><table class="data-table"><thead><tr><th>${compact?'COW':sortHeader('COW','name')}</th><th>Region / district</th><th class="right">${compact?'Tickets':sortHeader('Tickets','tickets')}</th><th class="right">${compact?'Restore hrs':sortHeader('Restore hrs','durationMinutes')}</th><th class="right">${compact?'Breaches':sortHeader('Breaches','breached')}</th><th class="right">SLA</th></tr></thead><tbody>${groups.map(g=>`<tr><td><button class="table-link" data-site="${e(g.name)}">${e(g.name)}</button><span class="subline">${e(g.rows[0]?.site_name||'')}</span></td><td>${e(g.region)}<span class="subline">${e(g.district)}</span></td><td class="right">${number(g.tickets)}${g.tickets>=2?'<span class="subline">Recurring</span>':''}</td><td class="right">${hours(g.durationMinutes)}</td><td class="right">${number(g.breached)}</td><td class="right"><span class="rate">${number(g.slaCompliance,1)}${num(g.slaCompliance)?'%':''}</span></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching sites.</td></tr>'}</tbody></table></div>${compact?'':pager(filteredTotal)}</section>`;
}
function sitesView(){const rows=periodRecords();return `${metricStrip(summarize(rows))}${siteTable(rows)}`;}
function ticketView(){const all=periodRecords(),rows=sorted(all.filter(r=>!state.query||[r.ticket_number,r.site_id,r.site_name,r.root_cause,r.repair_details].some(v=>String(v||'').toLowerCase().includes(state.query.toLowerCase()))));state.page=Math.min(state.page,Math.max(0,Math.ceil(rows.length/25)-1));const visible=rows.slice(state.page*25,state.page*25+25);return `<section class="panel"><div class="panel-title"><div><h2>Source ticket records</h2><p>${number(all.length)} records in ${e(monthName(state.period))}${state.site_id!=='all'?' · '+e(state.site_id):''}</p></div><button class="text-button" data-action="export">Export filtered tickets ${icon('download')}</button></div><div class="table-tools"><label class="search">${icon('search')}<input id="table-query" type="search" placeholder="Search TT, COW, root cause or repair" aria-label="Search tickets" value="${e(state.query)}"></label><span class="section-count">All timestamps use Saudi Arabia time</span></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>${sortHeader('Ticket / COW','ticket_number')}</th><th>${sortHeader('Created','created_at')}</th><th>Region / district</th><th>Impact</th><th>Root cause</th><th class="right">${sortHeader('Restore hrs','duration_minutes')}</th><th>SLA outcome</th></tr></thead><tbody>${visible.map(r=>`<tr><td><button class="table-link" data-ticket="${e(r.id)}">${e(r.ticket_number)}</button><span class="subline">${e(r.site_id||'Unknown')} &nbsp;<span class="priority ${r.site_label?.includes('VIP')?'vip':''}">${e(r.site_label)}</span></span></td><td>${e(dateName(r.created_date))}<span class="subline">${e(stamp(r.created_at).split(', ')[1]||'')}</span></td><td>${e(r.region)}<span class="subline">${e(r.district)}</span></td><td><span class="impact ${r.service_impact==='No impact'?'no':''}">${e(r.service_impact)}</span><span class="subline">${e(r.severity)}</span></td><td>${e(r.root_cause)}${r.quality_flags?.length?'<span class="ticket-alert" title="Source data check">△</span>':''}</td><td class="right">${hours(r.duration_minutes)}</td><td>${r.sla_excluded?'<span class="rate">Excluded</span>':r.sla_breached===true?'<span class="rate bad">Breached</span>':r.sla_breached===false?'<span class="rate good">Within SLA</span>':'<span class="muted">Unrecorded</span>'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No tickets match these filters.</td></tr>'}</tbody></table></div>${pager(rows.length)}</section>`;}
function reviewScope(){return Object.fromEntries(['period','region','district','service_impact','scope','vendor','severity','site_label','root_cause','site_id','reportView','year','week','duration_bucket'].map(k=>[k,state[k]]));}
function reviewKey(){return JSON.stringify(reviewScope());}
function localReview(){try{return JSON.parse(localStorage.getItem('performance-review:'+reviewKey()))||{commentary:'',actions:''};}catch{return {commentary:'',actions:''};}}
function persistDraft(){if(!data||!reviewDirty)return;localStorage.setItem('performance-review:'+reviewKey(),JSON.stringify({...reviewDraft,updated_at:new Date().toISOString()}));reviewDirty=false;}
function printNotes(){const r=localReview();return `<section class="print-notes"><h2>${e(monthName(state.period))} · Review commentary</h2><h3>Management commentary</h3><p>${e(r.commentary||'No commentary recorded for this scope.')}</p><h3>Priority actions</h3><p>${e(r.actions||'No actions recorded for this scope.')}</p><h3>Calculation basis</h3><p>Tickets are grouped by Create Date. Restoration hours use the recorded workbook duration. SLA uses explicit source outcomes after SLA exemptions. Source through ${e(dateName(data.meta.max_date))}. Duration formula verified against decoded PBIX rows. Live periods correct the legacy fixed-date and comparison defects documented in Formulas & criteria. Network availability is not calculated.</p></section>`;}
function reviewView(){const records=periodRecords(),s=summarize(records),p=compare(),causes=groupBy(records,'root_cause'),top=causes[0],regions=groupBy(records,'region');reviewDraft=localReview();reviewDirty=false;const key=reviewKey();if(source==='database'&&db){const token=++reviewToken;db.getReview(key).then(r=>{if(!r||token!==reviewToken||state.view!=='review'||reviewDirty)return;reviewDraft=r;$('#review-commentary').value=r.commentary;$('#review-actions').value=r.actions;$('#review-state').textContent='Saved in PostgreSQL · '+stamp(r.updated_at);localStorage.setItem('performance-review:'+key,JSON.stringify(r));}).catch(err=>toast('Could not load shared review notes: '+err.message));}
  return `<div class="review-heading"><div><h2>${e(monthName(state.period))} performance review</h2><p>${e(state.region==='all'?'National network':state.region)} · ${e(state.service_impact==='all'?'All impacts':state.service_impact)} · ${state.scope==='powerbi'?'Power BI monthly scope':'All recorded faults'}</p></div><span class="review-code">STC COW / UC04</span></div>${kpis(s,p)}<div class="review-grid"><section class="panel"><div class="panel-title"><div><h2>Review commentary</h2><p>Notes are saved for this month and selected filter scope</p></div>${icon('note')}</div><form id="review-form" class="form-grid"><label>Management commentary<textarea id="review-commentary" rows="7" placeholder="Record the month’s main findings and operational context…">${e(reviewDraft.commentary)}</textarea></label><label>Priority actions, owners and due dates<textarea id="review-actions" rows="6" placeholder="Action — Owner — Due date — Status">${e(reviewDraft.actions)}</textarea></label><div class="review-save-row"><span id="review-state">${source==='database'?'Shared PostgreSQL review':'Saved on this browser until database synchronization is active'}</span><button type="submit" class="button primary">${icon('check')}Save review</button></div></form></section><section class="panel"><div class="panel-title"><div><h2>Results for discussion</h2><p>Calculated from the selected records</p></div></div><div class="review-summary"><div><div class="item-label">Volume and restoration</div><p>${number(s.tickets)} tickets across ${number(s.sites)} sites. ${hours(s.durationMinutes)} recorded restoration hours, with a mean of ${hours(s.mttr)} hours.</p></div><div><div class="item-label">Leading cause</div><p>${top?e(top.name)+' accounts for '+number(top.tickets)+' tickets ('+number(top.tickets/Math.max(s.tickets,1)*100,1)+'%).':'No root cause records for this scope.'}</p></div><div><div class="item-label">Regional concentration</div><p>${regions[0]?e(regions[0].name)+' has the largest ticket volume: '+number(regions[0].tickets)+' tickets.':'No matching regional records.'}</p></div><div><div class="item-label">SLA and recurrence</div><p>${number(s.slaCompliance,1)}${num(s.slaCompliance)?'%':''} SLA compliance across ${number(s.slaEligible)} eligible records. ${number(s.breached)} breaches and ${number(s.repeatSites)} sites with two or more tickets.</p></div><div><div class="item-label">Source checks</div><p>${number(s.qualityIssues)} records have source date or duration inconsistencies. ${number(s.missingDuration)} have no recorded duration.</p></div></div><button class="button secondary print-hide" data-action="print" style="margin-top:24px">${icon('file')}Print monthly review</button></section></div>`;
}
function settingsView(){const m=data?.meta,q=m?.quality||{},connected=source==='database';return `<div class="settings-grid"><section class="panel"><div class="panel-title"><div><h2>PostgreSQL connection</h2><p>Use the project selected for COW performance</p></div><span class="connection-badge ${connected?'live':''}">${connected?'Connected':'Not synchronized'}</span></div><form class="form-grid" id="connection-form"><label>Project URL<input type="url" id="project-url" required value="${e(db?.url||localStorage.getItem('performance-project-url')||config.projectUrl||'')}"></label><label>Publishable / anon key<input id="project-key" autocomplete="off" type="password" value="${e(db?.key||localStorage.getItem('performance-project-key')||config.publishableKey||'')}" placeholder="sb_publishable_…" required></label><p class="help">Use the client publishable key from the project API settings. Database secrets and service-role keys are rejected.</p>${db?.session?`<p class="status-line">Signed in as <strong>${e(db.session.user?.email||'Database user')}</strong><br>Performance role: ${e(member?.role||'Checking access')}</p><div style="display:flex;gap:9px;flex-wrap:wrap"><button class="button primary" type="submit">${icon('database')}Reload database</button><button type="button" class="button secondary" id="logout-db">Sign out</button></div>`:`<label>Email<input id="db-email" type="email" autocomplete="username" required placeholder="Your approved account"></label><label>Password<input id="db-password" type="password" autocomplete="current-password" required></label><button class="button primary" type="submit">${icon('lock')}Sign in & load data</button>`}<p class="role-note">Access is controlled by performance_members and row-level policies. Database loading and imports require the schema in the repository’s database folder.</p></form><div class="link-row"><a href="https://supabase.com/dashboard/project/vtsqazxhszbmwiswthgt/settings/api" target="_blank" rel="noopener noreferrer">Project API settings</a><a href="https://github.com/Bannaga-Abdalmuhsin/performance/tree/main/database" target="_blank" rel="noopener noreferrer">Database setup</a></div></section><section class="panel"><div class="panel-title"><div><h2>Source and coverage</h2><p>Cumulative source records with Power BI analysis criteria</p></div>${icon('layers')}</div><dl class="source-list"><div><dt>Current source</dt><dd>${connected?'Authenticated PostgreSQL records':m?(m.source_drive_id?'Cumulative data snapshot':'Power BI model snapshot'):'No dataset loaded'}</dd></div><div><dt>Workbook / sheet</dt><dd>${e(m?.source_workbook||'—')}<br><span class="muted">${e(m?.source_sheet||'—')}</span></dd></div><div><dt>Power BI reference</dt><dd>${e(m?.source_pbix||'Weekly Overview V3.pbix')}<br><span class="muted">All five source pages extracted</span></dd></div><div><dt>Reporting coverage</dt><dd>${dateName(m?.min_date)} – ${dateName(m?.max_date)}<br><span class="muted">Asia/Riyadh (UTC+03:00)</span></dd></div><div><dt>Import reconciliation</dt><dd>${number(m?.raw_record_count)} source rows − ${number(m?.duplicates_removed)} duplicates − ${number(m?.quarantined_record_count||0)} rows for review = ${number(m?.record_count)} records</dd></div></dl></section><section class="panel"><div class="panel-title"><div><h2>Refresh performance data</h2><p>Preview an import before saving it to PostgreSQL</p></div>${icon('upload')}</div><p class="status-line">Upload the prepared JSON.GZ dataset or a CSV export. For PBIX use scripts/extract_powerbi.py; for the original XLSB use scripts/extract_data.py. CSV headers may use the original source names. Each ticket keeps its richest original row, even when the site or severity differs. Upload the full cumulative file; the checked snapshot becomes live on every connected dashboard.</p><div class="upload-zone"><div>Choose a performance data file</div><p>CSV, JSON or JSON.GZ · operational files stay out of the public repository</p><input id="import-file" type="file" accept=".csv,.json,.gz" aria-label="Choose performance data file"></div><div id="import-preview" class="import-summary">No file selected.</div><div style="display:flex;gap:9px;margin-top:17px;flex-wrap:wrap"><button class="button secondary" id="preview-import" ${!pendingImport?'disabled':''}>Preview data</button><button class="button primary" id="save-import" ${!pendingImport||!db?.session?'disabled':''}>${icon('database')}Save to PostgreSQL</button></div><p class="panel-foot">Upload a complete cumulative file. Records are staged in a new snapshot; only a verified completed snapshot becomes live. The previous version remains available if an upload fails. Source data is never uploaded to GitHub.</p>${source==='snapshot'&&db?.session&&!m?.import_id?'<button class="text-button" id="import-snapshot" style="margin-top:16px">Import the attached snapshot into PostgreSQL '+icon('arrow')+'</button>':''}</section><section class="panel"><div class="panel-title"><div><h2>Source data checks</h2><p>Retained for review, without changing the original file</p></div>${icon('info')}</div><div class="checks">${[['Duplicate rows removed',m?.duplicates_removed],['Rows set aside for review',m?.quarantined_record_count||0],['Missing recorded duration',q.missing_recorded_duration],['Cleared before create date',q.cleared_before_created],['Cleared before referral',q.cleared_before_referral],['Duration differs from create-to-clear',q.duration_differs_from_create_to_clear],['Missing cleared date',q.missing_cleared_date]].map(([label,n])=>`<div class="check-row"><span>${label}</span><b>${number(n)}</b></div>`).join('')}</div>${m?.quarantined_rows?.length?`<details><summary>Review ${number(m.quarantined_rows.length)} source rows</summary><ul>${m.quarantined_rows.map(r=>`<li>Row ${number(r.row)}: <b>${e(r.ticket_number||'Missing ticket')}</b> — ${e(r.reason)}</li>`).join('')}</ul></details>`:''}<p class="panel-foot">Rows with invalid ticket numbers or create dates are preserved separately for review and excluded from charts. Date inconsistencies remain flagged in the ticket drawer. The decoded duration formula and source SLA outcomes are preserved. Completed Supabase uploads refresh all six dashboards automatically every 30 seconds while this tab is visible.</p><button class="text-button" data-action="method" style="margin-top:15px">Open full calculation notes ${icon('arrow')}</button></section></div>`;}
function render(){
  persistDraft();const [title,subtitle]=titles[state.view];$('#page-title').textContent=title;$('#page-subtitle').textContent=subtitle;
  document.title=`${title} · stc COW`;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));
  $('.filters').hidden=['settings','formulas'].includes(state.view);$('.scope-caption').hidden=['settings','formulas'].includes(state.view);if(['settings','formulas'].includes(state.view))$('#extra-filters').hidden=true;
  const labels=[];if(state.site_id!=='all')labels.push(state.site_id);if(state.root_cause!=='all')labels.push(state.root_cause);if(state.duration_bucket!=='all')labels.push(state.duration_bucket);
  const criterion=reportProfile(profiles,activeReportId());
  $('#scope-description').innerHTML=e((state.scope==='powerbi'?`${criterion.name||'Power BI'} · blank Parent TT · ${(criterion.excluded_root_causes||[]).length} root cause exclusion values.`:'All recorded faults within the page’s service-impact group; parent and root cause exclusions removed.')+(criterion.impact_mode==='NSA'?' NSA includes every impact except Outage, as in the PBIX.':'')+(labels.length?' Filtered to '+labels.join(' · '):''))+(labels.length?' <button class="text-button" data-action="clear-drill">Clear selection</button>':'');

  if(!data&&!['settings','formulas'].includes(state.view))$('#content').innerHTML=`<section class="panel empty">${icon('database')}<h2>Connect your performance data</h2><p>Sign in to the PostgreSQL project or preview a prepared source file to begin the monthly review.</p><button class="button primary" data-go="settings">Open data & settings ${icon('arrow')}</button></section>`;
  else $('#content').innerHTML=REPORTS[state.view]?renderReport(activeModel(),state,data.meta):state.view==='formulas'?renderFormulaAudit(audit,profiles):({causes:causeView,sites:sitesView,tickets:ticketView,review:reviewView,settings:settingsView})[state.view]();
  if(state.view==='settings'&&pendingImport)showImportPreview();fillIcons($('#content'));
}
function navigate(view){if(!titles[view])return;persistDraft();reviewToken++;state.view=view;if(REPORTS[view]){state.reportView=view;state.duration_bucket='all';}state.page=0;state.query='';state.sort=view==='sites'?'tickets':'created_at';state.dir=-1;$('#sidebar').classList.remove('open');fillFilters();render();history.replaceState(null,'','#'+view);}
function showDetail(id){const r=recordsById.get(id);if(!r)return;const fields=[['COW',r.site_id],['Region / district',r.region+' / '+r.district],['Location',r.site_name],['Service impact',r.service_impact],['Severity / vendor',r.severity+' / '+r.vendor],['Site priority',r.site_label],['Created',stamp(r.created_at)],['Cleared',stamp(r.cleared_at)],['Referred to ACES',stamp(r.referred_at)],['Recorded restoration',hours(r.duration_minutes)+' hrs'],['Source SLA allowance',hours(r.sla_minutes)+' hrs'],['Legacy DAX duration',hours(r.duration_dax_minutes)+' hrs'],['Record key',r.source_key||r.id],['Parent TT',r.parent_tt||'Blank'],['Impact start',stamp(r.impact_start)],['Impact finish',stamp(r.impact_finish)],['Decoded / source row',r.source_row]];
  $('#detail-content').innerHTML=`<div class="detail-heading"><div><h2>${e(r.ticket_number)}</h2><span class="muted" style="font-size:11px">${e(r.site_id)} · ${e(r.root_cause)}</span></div><span class="impact ${r.service_impact==='No impact'?'no':''}">${e(r.service_impact)}</span></div><dl class="detail-grid">${fields.map(([k,v])=>`<div><dt>${k}</dt><dd>${e(v??'—')}</dd></div>`).join('')}</dl><div class="detail-block"><h3>Repair details</h3><p>${e(r.repair_details||'No repair details recorded.')}</p></div><div class="detail-block"><h3>SLA outcome</h3><p>${r.sla_excluded?'Explicitly excluded from SLA compliance':r.sla_breached===true?'Recorded as breached':r.sla_breached===false?'Recorded as within SLA':'No source outcome recorded'}${r.exclusion_reason?' · '+e(r.exclusion_reason):''}</p></div>${r.quality_flags?.length?`<div class="detail-block warn"><h3>Source data checks</h3><p>${r.quality_flags.map(e).join('<br>')}</p></div>`:''}`;$('#detail-dialog').showModal();
}
function download(text,name,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportData(){if(!data)return;const rows=periodRecords().filter(r=>!state.query||[r.ticket_number,r.site_id,r.site_name,r.root_cause,r.repair_details].some(v=>String(v||'').toLowerCase().includes(state.query.toLowerCase())));download(exportCSV(rows),`stc-COW-performance-${state.period}-${state.region}.csv`);toast(number(rows.length)+' filtered records exported.');}
function printReview(){if(!data)return;if(state.view==='settings'){navigate('overview');}persistDraft();window.print();}
function showImportPreview(){if(!pendingImport||!$('#import-preview'))return;const p=pendingImport;$('#import-preview').innerHTML=`<b>${number(p.records.length)}</b> records · ${dateName(p.meta.min_date)} – ${dateName(p.meta.max_date)}<br>${number(p.meta.duplicates_removed||0)} duplicate rows removed · ${number(p.meta.quarantined_record_count||0)} rows set aside for review${p.rejected?.length?'<div class="warning-inline">'+p.rejected.slice(0,3).map(r=>'Row '+r.row+': '+e(r.reason)).join('<br>')+'</div>':''}`;$('#preview-import').disabled=false;$('#save-import').disabled=!db?.session;}
async function readImport(file){
  let text;if(file.name.toLowerCase().endsWith('.gz')){if(!window.DecompressionStream)throw new Error('This browser cannot open GZIP. Decompress the JSON file first.');text=await new Response(file.stream().pipeThrough(new DecompressionStream('gzip'))).text();}else text=await file.text();
  let parsed,meta={};if(file.name.toLowerCase().endsWith('.csv'))parsed=parseCSV(text);else{const doc=JSON.parse(text);parsed=Array.isArray(doc)?doc:doc.records;meta=doc.meta||{};}
  if(!Array.isArray(parsed))throw new Error('The file needs a records array or a CSV header row.');
  const result=normalizeRecords(parsed);if(!result.records.length)throw new Error('No valid dated records found. CSV requires Ticket Number/Create Date, or ticket_number/created_at.');
  const prepared=meta.deduplication_policy===DEDUPLICATION_POLICY&&meta.record_count===parsed.length,dates=result.records.map(r=>r.created_date).sort();pendingImport={...result,meta:{...meta,source_workbook:meta.source_workbook||file.name,source_sheet:meta.source_sheet||'Imported records',profile:meta.profile||profile,record_count:result.records.length,raw_record_count:prepared?meta.raw_record_count:parsed.length,duplicates_removed:(prepared?meta.duplicates_removed||0:0)+result.duplicates,quarantined_record_count:(prepared?meta.quarantined_record_count||0:0)+result.rejected.length,quarantined_rows:[...(prepared?meta.quarantined_rows||[]:[]),...result.rejected],deduplication_policy:DEDUPLICATION_POLICY,grain:'Ticket Number',format_version:3,min_date:dates[0],max_date:dates.at(-1),timezone:'Asia/Riyadh'}};showImportPreview();
}
function databaseNotice(){notice(`${icon('database')}<span>PostgreSQL data · <b>${number(data.records.length)}</b> records · source through <b>${dateName(data.meta.max_date)}</b></span><span class="notice-end">Auto refresh · checked ${new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Riyadh'})}</span><button class="text-button" id="refresh-now">Refresh now</button>`,'success');}
function startAutoRefresh(){if(refreshTimer)clearInterval(refreshTimer);refreshTimer=setInterval(()=>checkForUpdates(),30000);refreshTimer?.unref?.();}
async function checkForUpdates(force=false){if(refreshBusy||importBusy||source!=='database'||!db?.session||document.visibilityState==='hidden')return;refreshBusy=true;try{const latest=await db.latest();if(!latest)throw new Error('No completed snapshot is visible. Verify your performance access.');if(latest.id!==data?.meta.import_id){await loadDatabase();toast('New completed Supabase snapshot loaded across all dashboards.');}else {databaseNotice();if(force)toast('All dashboards use the latest completed Supabase snapshot.');}}catch(err){notice(`${icon('alert')}<span>Live refresh paused: ${e(err.message)} Displaying the last verified snapshot.</span><button class="text-button" id="refresh-now">Retry refresh</button>`,'warn');}finally{refreshBusy=false;}}
async function loadDatabase(){member=await db.member();$('#account-name').textContent=db.session.user?.email||'Database account';notice(`<span class="spinner"></span><span>Loading PostgreSQL records…</span>`);const dataset=await db.load(n=>notice(`<span class="spinner"></span><span>Loading PostgreSQL records… ${number(n)} read</span>`));setData(dataset,'database');}
async function connect(form){const button=form.querySelector('[type="submit"]');button.disabled=true;try{const url=$('#project-url').value.trim(),key=$('#project-key').value.trim();if(!db||db.url!==url||db.key!==key)db=new PerformanceDatabase(url,key);localStorage.setItem('performance-project-url',url);localStorage.setItem('performance-project-key',key);if(!db.session){await db.login($('#db-email').value.trim(),$('#db-password').value);$('#db-password').value='';}await loadDatabase();navigate('overview');toast('Performance data loaded from PostgreSQL.');}catch(err){toast(err.message);notice(`${icon('alert')}<span>${e(err.message)}${data?' The previously loaded source remains in view.':''}</span>`,'warn');}finally{button.disabled=false;}}
async function saveImport(dataset){if(!db?.session)throw new Error('Sign in to PostgreSQL before importing.');notice(`<span class="spinner"></span><span>Saving performance records to PostgreSQL…</span>`);importBusy=true;try{await db.import(dataset.records,dataset.meta,(n,total)=>notice(`<span class="spinner"></span><span>Saving to PostgreSQL… ${number(n)} / ${number(total)}</span>`));pendingImport=null;await loadDatabase();navigate('overview');toast('The import is complete and every dashboard uses the verified snapshot.');}finally{importBusy=false;}}
document.addEventListener('click',async(ev)=>{
  const b=ev.target.closest('button,a');if(!b)return;if(b.closest?.('.bi-chart-row,.bi-kpis,.bi-chart-dialog'))ev.preventDefault();
  try{
    if(b.dataset.action==='chart-download'){const panel=b.closest('.bi-panel'),svg=panel?.querySelector('.bi-scroll > svg');if(svg){const keys=[...panel.querySelectorAll('.bi-legend>span')].map(el=>{const marker=el.querySelector('i');return {name:el.textContent.trim(),color:marker?.style.getPropertyValue('--legend-color')||marker?.style.backgroundColor||'#4f008c',line:marker?.classList.contains('line')};});download(createChartExport(svg.outerHTML,panel.querySelector('h2')?.textContent||'Performance chart',keys),'stc-COW-'+panel.dataset.chartId+'-'+state.period+'.svg','image/svg+xml;charset=utf-8');}return;}
    if(b.dataset.action==='chart-expand'){const panel=b.closest('.bi-panel'),svg=panel?.querySelector('.bi-scroll > svg');if(svg){const heading=panel.querySelector('h2')?.textContent||'Performance chart',legend=panel.querySelector('.bi-legend')?.outerHTML||'';$('#chart-dialog-content').innerHTML=`<h2>${e(heading)}</h2>${legend}<div class="bi-scroll bi-expanded-scroll">${svg.outerHTML}</div>`;$('#chart-dialog').showModal();}return;}
    if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.go){navigate(b.dataset.go);return;}
    if(b.classList.contains('close-dialog')){b.closest('dialog').close();return;}
    if(b.dataset.ticket){showDetail(b.dataset.ticket);return;}
    if(b.dataset.region){persistDraft();state.region=b.dataset.region;state.district='all';state.site_id='all';fillFilters();render();return;}
    if(b.dataset.cause){persistDraft();state.root_cause=b.dataset.cause;fillFilters();$('#extra-filters').hidden=false;$('#more-filters').setAttribute('aria-expanded','true');navigate('tickets');return;}
    if(b.dataset.district){persistDraft();state.district=b.dataset.district;fillFilters();navigate('tickets');return;}
    if(b.dataset.site){persistDraft();state.site_id=b.dataset.site;navigate('tickets');return;}
    if(b.dataset.severity){state.severity=b.dataset.severity;fillFilters();navigate('tickets');return;}
    if(b.dataset.duration){state.duration_bucket=b.dataset.duration;navigate('tickets');return;}
    if(b.id==='refresh-now'){await checkForUpdates(true);return;}
    if(b.dataset.priority){persistDraft();state.site_label=b.dataset.priority;fillFilters();navigate('tickets');return;}
    if(b.dataset.sort){if(state.sort===b.dataset.sort)state.dir*=-1;else{state.sort=b.dataset.sort;state.dir=-1;}render();return;}
    if(b.dataset.page){state.page+=b.dataset.page==='next'?1:-1;render();return;}
    if(b.dataset.action==='clear-drill'){persistDraft();state.site_id='all';state.root_cause='all';state.duration_bucket='all';fillFilters();render();return;}
    if(b.id==='method-button'||b.dataset.action==='method'){$('#method-dialog').showModal();return;}
    if(b.id==='export-csv'||b.dataset.action==='export'){exportData();return;}
    if(b.id==='print-review'||b.dataset.action==='print'){printReview();return;}
    if(b.id==='more-filters'){const el=$('#extra-filters');el.hidden=!el.hidden;b.setAttribute('aria-expanded',String(!el.hidden));return;}
    if(b.id==='menu-toggle'){$('#sidebar').classList.toggle('open');return;}
    if(b.id==='account-button'){navigate('settings');return;}
    if(b.id==='reset-filters'){persistDraft();Object.assign(state,{region:'all',district:'all',vendor:'all',severity:'all',site_label:'all',root_cause:'all',site_id:'all',scope:'powerbi',service_impact:'Outage',duration_bucket:'all',page:0});fillFilters();render();return;}
    if(b.id==='logout-db'){clearInterval(refreshTimer);refreshTimer=null;await db.logout();member=null;data=null;recordsById.clear();source='none';$('#account-name').textContent='Review workspace';$('#sidebar-source').textContent='Database signed out';$('#sidebar-dot').classList.remove('live');$('#nav-count').textContent='—';$('#export-csv').disabled=true;$('#print-review').disabled=true;notice('Signed out of the performance database.');render();return;}
    if(b.id==='preview-import'&&pendingImport){setData(pendingImport,'preview');navigate('overview');toast('Import preview loaded. The data has not been saved to PostgreSQL.');return;}
    if(b.id==='save-import'&&pendingImport){b.disabled=true;await saveImport(pendingImport);return;}
    if(b.id==='import-snapshot'&&data){b.disabled=true;await saveImport(data);return;}
  }catch(err){toast(err.message);b.disabled=false;if(['save-import','import-snapshot'].includes(b.id))notice(`${icon('alert')}<span>${e(err.message)}</span>`,'warn');}
});
// The chart itself is SVG, so it has its own accessible selection handler.
document.addEventListener('click',ev=>{const target=ev.target.closest('[data-month]');if(target){persistDraft();state.period=target.dataset.month;state.year=Number(state.period.slice(0,4));state.followLatest=false;state.page=0;fillFilters();render();}});
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('[data-month]')){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
for(const [id,key]of [['period-filter','period'],['region-filter','region'],['district-filter','district'],['impact-filter','service_impact'],['scope-filter','scope'],['vendor-filter','vendor'],['severity-filter','severity'],['label-filter','site_label'],['cause-filter','root_cause'],['year-filter','year'],['week-filter','week']])$('#'+id).addEventListener('change',ev=>{if(key==='period'&&(!ev.target.value||!coverageFor(data?.meta||{},ev.target.value))){ev.target.value=state.period;toast('Choose a month within the loaded source coverage.');return;}persistDraft();reviewToken++;state[key]=['year','week'].includes(key)?Number(ev.target.value):ev.target.value;if(['period','year','week'].includes(key)){state.followLatest=false;if(key==='period')state.year=Number(state.period.slice(0,4));if(key==='year'){state.period=String(state.year)+state.period.slice(4);state.week=Math.min(state.week,weeksInYear(state.year));}}state.site_id='all';state.page=0;if(key==='region')state.district='all';fillFilters();render();});
document.addEventListener('input',ev=>{
  if(ev.target.id==='table-query'){const value=ev.target.value,position=ev.target.selectionStart;state.query=value;state.page=0;render();const input=$('#table-query');input.focus();try{input.setSelectionRange(position,position);}catch{}}
  if(ev.target.id==='review-commentary'||ev.target.id==='review-actions'){reviewDraft={commentary:$('#review-commentary').value,actions:$('#review-actions').value};reviewDirty=true;$('#review-state').textContent='Unsaved changes';}
});
document.addEventListener('change',async ev=>{if(ev.target.id==='import-file'&&ev.target.files[0]){try{await readImport(ev.target.files[0]);}catch(err){pendingImport=null;toast(err.message);$('#import-preview').textContent=err.message;$('#preview-import').disabled=true;$('#save-import').disabled=true;}}});
document.addEventListener('submit',async ev=>{ev.preventDefault();if(ev.target.id==='connection-form'){await connect(ev.target);return;}if(ev.target.id==='review-form'){reviewDraft={commentary:$('#review-commentary').value,actions:$('#review-actions').value};reviewDirty=true;persistDraft();try{if(source==='database'){await db.saveReview({review_key:reviewKey(),period:state.period+'-01',scope:reviewScope(),...reviewDraft});$('#review-state').textContent='Saved in PostgreSQL';toast('Monthly review saved to PostgreSQL.');}else{$('#review-state').textContent='Saved on this browser';toast('Review saved on this browser.');}}catch(err){$('#review-state').textContent='Saved on this browser. Database save failed.';toast(err.message);}}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkForUpdates();});
function showChartTip(ev){const item=ev.target.closest?.('[data-tip]'),tip=$('#chart-tooltip');if(!item){tip.hidden=true;return;}tip.textContent=item.dataset.tip;tip.hidden=false;const rect=item.getBoundingClientRect?.(),x=ev.clientX??rect?.x??0,y=ev.clientY??rect?.y??0;tip.style.left=Math.max(10,Math.min(x+16,(window.innerWidth||1200)-320))+'px';tip.style.top=Math.max(10,Math.min(y+14,(window.innerHeight||900)-230))+'px';}
document.addEventListener('pointermove',showChartTip);
document.addEventListener('focusin',showChartTip);
document.addEventListener('pointerout',ev=>{if(!ev.relatedTarget?.closest?.('[data-tip]'))$('#chart-tooltip').hidden=true;});
document.addEventListener('focusout',()=>$('#chart-tooltip').hidden=true);
document.addEventListener('click',()=>$('#chart-tooltip').hidden=true);
window.addEventListener('beforeunload',persistDraft);
async function startup(){
  fillIcons();$('#export-csv').disabled=true;$('#print-review').disabled=true;
  if(titles[location.hash.slice(1)]){state.view=location.hash.slice(1);if(REPORTS[state.view])state.reportView=state.view;}
  try{const responses=await Promise.all([fetch('report-profile.json'),fetch('report-profiles.json'),fetch('formula-audit.json')]);if(responses.some(r=>!r.ok))throw new Error('Report criteria could not be loaded.');[profile,profiles,audit]=await Promise.all(responses.map(r=>r.json()));}catch(err){notice(e(err.message),'warn');render();return;}
  const key=localStorage.getItem('performance-project-key')||config.publishableKey,url=localStorage.getItem('performance-project-url')||config.projectUrl;
  if(key){try{db=new PerformanceDatabase(url,key);if(db.session){await loadDatabase();return;}}catch(err){notice(`${icon('alert')}<span>${e(err.message)}</span>`,'warn');toast(err.message);}}
  if(config.privateSnapshot){try{const r=await fetch(config.privateSnapshot);if(!r.ok)throw new Error('The private source snapshot could not be loaded.');const blob=await r.blob(),head=new Uint8Array(await blob.slice(0,2).arrayBuffer());const text=head[0]===31&&head[1]===139?await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text():await blob.text();setData(JSON.parse(text),'snapshot');return;}catch(err){toast(err.message);}}
  notice(`${icon('lock')}<span>Connect your PostgreSQL project to load performance records.</span>`);render();
}
export const ready=startup();
export {state,setData,render,navigate};
